"""Overview / demo workspace page."""

from __future__ import annotations

import streamlit as st
from ui.state import get_validation

st.title("ActuaryBench")
st.caption("Group-health experience study & preliminary pricing indication workbench")

if st.session_state.get("data_source") == "synthetic":
    st.info(
        "**Synthetic demo data.** Every record and value in this workspace is generated by "
        "a fixed-seed synthetic generator. It does not represent any real insurer, employer, "
        "member or claim.",
        icon=":material/science:",
    )

exp = st.session_state.mapped_exposures
clm = st.session_state.mapped_claims

# Uploaded data is held as text until validation parses it, so numeric totals are taken
# only from the validated (typed) exposure rows — never from the raw mapped columns.
validation = get_validation()
with st.container(horizontal=True):
    st.metric("Exposure records", f"{len(exp):,}", border=True)
    st.metric("Claim records", f"{len(clm):,}", border=True)
    if validation is not None and validation[0].ok:
        ev = validation[0]
        st.metric(
            "Earned member-months (validated rows)",
            f"{ev.clean['earned_member_months'].sum():,.0f}",
            help=f"{ev.rows_out:,} of {ev.rows_in:,} exposure rows passed validation.",
            border=True,
        )
if validation is not None and not validation[0].ok:
    st.warning(
        "Exposure data is not structurally valid yet: " + "; ".join(validation[0].schema_errors),
        icon=":material/warning:",
    )

st.subheader("Workflow")
st.markdown(
    "1. **Data** — upload exposure & claims files (CSV/XLSX) or keep the synthetic demo.\n"
    "2. **Validation** — review every error, warning and exclusion.\n"
    "3. **Experience study** — member-months, frequency, severity, PMPM, loss ratio.\n"
    "4. **Assumptions & pricing** — versioned assumptions, trend, preliminary indicated rate.\n"
    "5. **Run history & reports** — reproducible run manifests and exports."
)

st.subheader("What this tool is not")
st.markdown(
    "- Not a production actuarial valuation system or regulatory reporting tool.\n"
    "- Does not calculate reserves, IBNR, or insurance-contract accounting measurements.\n"
    "- Outputs are preliminary indications for analyst review, not filed or binding rates."
)

with st.expander("Preview synthetic data"):
    st.dataframe(exp.head(50), hide_index=True)
    st.dataframe(clm.head(50), hide_index=True)
